SELECT table,name,rows,bytes_on_disk,marks,modification_time FROM system.parts WHERE database='quotes_async_t4' AND table IN ('quotes','quotes_daily') AND active ORDER BY table,name LIMIT 5000 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,skip_unavailable_shards=0 FORMAT CSVWithNames
